spec.setup_code:
var geometry = new api.THREE.BoxGeometry(1, 1, 1);
                var material = new api.THREE.MeshPhongMaterial({ color: 0xE8593C });
                var cube = new api.THREE.Mesh(geometry, material);
                cube.position.set(1, 1, 1);
                api.group.add(cube);
                var axes = new api.THREE.AxesHelper(3);
                api.group.add(axes);
                return {
                  update: function(t) {
                    cube.rotation.x = t * 0.02;
                    cube.rotation.y = t * 0.03;
                  }
                };

return {
                  draw: function(ctx, W, H, t, dt) {
                    ctx.fillStyle = '#F5F0E8';
                    ctx.fillRect(0, 0, W, H);
                    var cx = W/2, cy = H/2;
                    var scale = Math.min(W, H) / 12;
                    ctx.strokeStyle = '#CFC7B8';
                    ctx.lineWidth = 1;
                    for (var gx = -5; gx <= 5; gx++) {
                      ctx.beginPath();
                      ctx.moveTo(cx + gx * scale, 0);
                      ctx.lineTo(cx + gx * scale, H);
                      ctx.stroke();
                    }
                    for (var gy = -5; gy <= 5; gy++) {
                      ctx.beginPath();
                      ctx.moveTo(0, cy + gy * scale);
                      ctx.lineTo(W, cy + gy * scale);
                      ctx.stroke();
                    }
                    ctx.strokeStyle = '#8A8272';
                    ctx.lineWidth = 2;
                    ctx.beginPath();
                    ctx.moveTo(0, cy); ctx.lineTo(W, cy);
                    ctx.moveTo(cx, 0); ctx.lineTo(cx, H);
                    ctx.stroke();
                    var px = 3, py = 4;
                    var x = cx + px * scale;
                    var y = cy - py * scale;
                    ctx.fillStyle = '#E8593C';
                    ctx.beginPath();
                    ctx.arc(x, y, 8, 0, Math.PI * 2);
                    ctx.fill();
                    ctx.strokeStyle = '#E8593C';
                    ctx.setLineDash([4, 4]);
                    ctx.beginPath();
                    ctx.moveTo(cx, cy); ctx.lineTo(x, cy); ctx.lineTo(x, y);
                    ctx.stroke();
                    ctx.setLineDash([]);
                    ctx.fillStyle = '#333';
                    ctx.font = '14px sans-serif';
                    ctx.fillText('(' + px + ', ' + py + ')', x + 12, y - 12);
                  }
                };
